  @override
  String countsImportDone(num matched, String pieces) {
    String _temp0 = intl.Intl.pluralLogic(
      matched,
      locale: localeName,
      other: '$matched ವಸ್ತುಗಳನ್ನು ಎಣಿಸಲಾಗಿದೆ',
      one: '$matched ವಸ್ತು ಎಣಿಸಲಾಗಿದೆ',
    );
    return '$_temp0, $pieces ತುಂಡುಗಳು';
  }

